// Records are immutable data types
record Trail {
    name: string;
    miles: float;
    gainFeet: int;
}

record Waypoint {
    name: string;
    elevation: int;
}

fn main() -> void {
    let trail = Trail("Hidden Lake", 8.0, 2900);
    print($"{trail.name}: {trail.miles} mi, {trail.gainFeet} ft");

    // Use with to create modified copies
    // Note: colon syntax for field assignment
    let extended = trail with { miles: 10.5 };
    print($"Extended: {extended.miles} mi");

    let summit = Waypoint("Hidden Lake Peak", 7088);
    print($"{summit.name} at {summit.elevation} ft");
}

// Option uses T? syntax
// Some(value) for present, None for absent

fn findTrail(id: int) -> string? {
    if id == 1 {
        return Some("Cascade Pass");
    }
    if id == 2 {
        return Some("Sahale Arm");
    }
    return None;
}

fn main() -> void {
    let trail1 = findTrail(1);
    if trail1 != None {
        print($"Found: {trail1}");
    }

    let trail99 = findTrail(99);
    if trail99 == None {
        print("Trail not found in registry");
    }
}

// Result<T> for operations that may fail
// Return value directly for success
// Use Error.Validation for errors

fn checkPermit(partySize: int) -> Result<int> ~blocking {
    if partySize > 12 {
        return Error.Validation("Party size exceeds limit");
    }
    return partySize;
}

fn main() -> void {
    let small = checkPermit(4);
    print($"Party of 4: {small}");

    let large = checkPermit(15);
    print($"Party of 15: {large}");
}

// Use ? to propagate errors up the call stack

fn validateGroup(size: int) -> Result<int> ~blocking {
    if size > 12 {
        return Error.Validation("Group too large");
    }
    return size;
}

fn issuePermit(size: int) -> Result<string> ~blocking {
    let validSize = validateGroup(size)?;
    return $"Permit issued for {validSize} hikers";
}

fn main() -> void {
    let permit1 = issuePermit(6);
    print($"Result: {permit1}");

    let permit2 = issuePermit(20);
    print($"Result: {permit2}");
}

// Define domain specific errors
error TrailError {
    Closed;
    PermitRequired { zone: string; };
    WeatherAlert { condition: string; level: int; };
}

fn checkAccess(zone: string) -> Result<string, TrailError> ~blocking {
    if zone == "Glacier" {
        return TrailError.PermitRequired("Glacier Zone");
    }
    return $"{zone} is open";
}

fn main() -> void {
    let result1 = checkAccess("Meadows");
    if result1.IsOk {
        print($"Access: {result1.Value}");
    }

    let result2 = checkAccess("Glacier");
    if result2.IsError {
        print("Permit required for this zone");
    }
}

