// Railway oriented programming with Result

fn parseElevation(s: string) -> Result<int> ~blocking {
    if s == "5392" { return 5392; }
    return Error.Validation($"Invalid elevation: {s}");
}

fn validateAltitude(ft: int) -> Result<int> ~blocking {
    if ft > 0 { return ft; }
    return Error.Validation("Elevation must be positive");
}

fn main() -> void {
    // Map transforms success value
    let meters = parseElevation("5392").Map(ft => ft / 3.281);
    print($"In meters: {meters}");

    // Then chains Result returning functions
    let valid = parseElevation("5392").Then(e => validateAltitude(e));
    print($"Validated: {valid}");

    // UnwrapOr provides default on error
    let elev = parseElevation("bad").UnwrapOr(0);
    print($"With default: {elev}");
}

